typedef unsigned short vert_ref;

class cface
{
  vert_ref vert_refs[3];
public:
  vert_ref get_vert_ref(int i) const { return vert_refs[i]; }
};

template<class T> class vector
{
public:
  typedef const T* const_iterator;
  const_iterator begin() const;
  const_iterator end() const;
};

typedef vector<cface> cface_vect;

class cg_mesh
{
public:
  int get_num_verts() const;
  const cface_vect& get_cfaces() const;
};

void nglPrintf(const char*, ...);
void _assert(const char*, const char*, unsigned);
#define assert(e) ((e) ? (void)0 : _assert(#e, __FILE__, __LINE__))

static void fing_grind_cface (cg_mesh *colgeom, cface *hit_face)
{
  int half_idx = colgeom->get_num_verts () / 2 - 1;
  int i, low = 0, count = 0;

  for (i = 0; i < 3; i++)
    if (hit_face->get_vert_ref (i) <= half_idx)
      count++;

  if (count == 2)
    return;

  if (count != 1)
  {
    nglPrintf ("ERROR: Grinding geometry is wrong, ask for help on how to do it.\n");
    assert (false);
  }

  for (i = 0; i < 3; i++)
    if (hit_face->get_vert_ref (i) <= half_idx)
    {
      low = hit_face->get_vert_ref (i);
      break;
    }

  for (cface_vect::const_iterator it = colgeom->get_cfaces ().begin (); it != colgeom->get_cfaces ().end (); it++)
  {
    count = 0;

    for (i = 0; i < 3; i++)
      if ((*it).get_vert_ref (i) == low)
      {
        count++;
        break;
      }

    for (i = 0; i < 3; i++)
      if ((*it).get_vert_ref (i) == low - 1)
      {
        count++;
        break;
      }

    if (count == 2)
    {
      *hit_face = (*it);
      break;
    }
  }
}
